mapper.select:
SELECT c.*, u.real_name AS teacher_name FROM course c LEFT JOIN user u ON c.teacher_id = u.user_id WHERE c.is_deleted = 0
AND ( c.course_name LIKE CONCAT('%', #{keyword}, '%') OR c.course_code LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY c.create_time DESC, c.course_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT c.*, u.real_name AS teacher_name FROM course c
LEFT JOIN user u ON c.teacher_id = u.user_id
WHERE c.is_deleted = 0 AND c.status = 1 AND c.course_id != #{courseId}
ORDER BY avg_rating DESC, selection_count DESC
LIMIT #{limit}
